static int balanced_make(const std::vector<int>&xs,int lo,int hi,int&next,std::vector<int32_t>&a,std::vector<int32_t>&b){if(hi-lo==1)return xs[lo];int mid=(lo+hi)/2,l=balanced_make(xs,lo,mid,next,a,b),r=balanced_make(xs,mid,hi,next,a,b),u=next++;a[u]=l;b[u]=r;return u;}
static int group(int lo,int hi,bool balanced,int&next,std::vector<int32_t>&a,std::vector<int32_t>&b){std::vector<int>xs(hi-lo);std::iota(xs.begin(),xs.end(),lo);if(balanced)return balanced_make(xs,0,xs.size(),next,a,b);int u=lo;for(int x=lo+1;x<hi;x++){int v=next++;a[v]=u;b[v]=x;u=v;}return u;}
static double score_skeleton(int K,const std::vector<float>&D,bool after){std::vector<int32_t>a(2*K-1),b(2*K-1);int next=K;int G=group(3,K,K==7,next,a,b);int left=next++;a[left]=0;b[left]=after?2:1;int right=next++;a[right]=after?1:2;b[right]=G;int root=next++;a[root]=left;b[root]=right;std::vector<std::vector<int>>adj(2*K-2);for(int u=K;u<root;u++)for(int x:{a[u],b[u]}){adj[u].push_back(x);adj[x].push_back(u);}adj[left].push_back(right);adj[right].push_back(left);double L=0;for(int x=0;x<K;x++){std::vector<int>todo={x},par(2*K-2,-2),dist(2*K-2,0);par[x]=-1;for(size_t z=0;z<todo.size();z++){int u=todo[z];for(int v:adj[u])if(v!=par[u]){par[v]=u;dist[v]=dist[u]+1;todo.push_back(v);}}for(int y=x+1;y<K;y++)L+=D[x*K+y]*ldexp(1.,1-dist[y]);}return L;}
int main(){for(int big:{0,1}){int A=big?4096:9,N=big?4102:17,K=N-A+1;std::vector<int32_t>a(2*N-1),b(2*N-1);int next=N,rA=group(0,A,big,next,a,b),rG=group(A+2,N,big,next,a,b);int left=next++;a[left]=rA;b[left]=A;int right=next++;a[right]=A+1;b[right]=rG;int root=next++;a[root]=left;b[root]=right;std::vector<int32_t>ord,par,cnt,rep,ls,offs={0};std::vector<float>ws;compute_tree_summaries_blind(a.data(),b.data(),N,ord,par,cnt,rep);compute_clade_dyadic_profile(rA,N,a.data(),b.data(),rep.data(),128,ls,ws);offs.push_back(ls.size());std::set<int>S;if(big)S.insert(ls.begin(),ls.end());else S.insert(0);S.insert(A+1);S.insert(A+4);if(big){S.erase(A+4);S.insert(A+2);S.insert(A+3);}for(int x=A;x<N;x++){ls.push_back(x);ws.push_back(1);offs.push_back(ls.size());}
std::vector<int>yes,no;for(int i=0;i<N;i++)(S.count(i)?yes:no).push_back(i);std::vector<int32_t>ta(2*N-1),tb(2*N-1);next=N;int sy=balanced_make(yes,0,yes.size(),next,ta,tb),sn=balanced_make(no,0,no.size(),next,ta,tb);ta[next]=sy;tb[next]=sn;TrueTreeHLD oracle;oracle.build(ta.data(),tb.data(),N,111);oracle.dist_root.assign(2*N-1,0);std::vector<int>todo={2*N-2};for(size_t z=0;z<todo.size();z++){int u=todo[z];if(u<N)continue;for(int x:{ta[u],tb[u]}){oracle.dist_root[x]=oracle.dist_root[u]+(x<N?1.f:x==sy?1.f:0.f);todo.push_back(x);}}CUDA_CHECK(cudaMemcpy(oracle.d_dist_root,oracle.dist_root.data(),oracle.dist_root.size()*sizeof(float),cudaMemcpyHostToDevice));
int32_t *doff,*dl;float *dw,*dD;CUDA_CHECK(cudaMalloc(&doff,offs.size()*sizeof(int32_t)));CUDA_CHECK(cudaMalloc(&dl,ls.size()*sizeof(int32_t)));CUDA_CHECK(cudaMalloc(&dw,ws.size()*sizeof(float)));CUDA_CHECK(cudaMalloc(&dD,K*K*sizeof(float)));CUDA_CHECK(cudaMemcpy(doff,offs.data(),offs.size()*sizeof(int32_t),cudaMemcpyHostToDevice));CUDA_CHECK(cudaMemcpy(dl,ls.data(),ls.size()*sizeof(int32_t),cudaMemcpyHostToDevice));CUDA_CHECK(cudaMemcpy(dw,ws.data(),ws.size()*sizeof(float),cudaMemcpyHostToDevice));dim3 block(16,16),grid((K+15)/16,(K+15)/16);k_build_true_condensed_D<<<grid,block>>>(K,doff,dl,dw,oracle.d_head,oracle.d_parent,oracle.d_depth,oracle.d_dist_root,dD);std::vector<float>D(K*K);CUDA_CHECK(cudaMemcpy(D.data(),dD,K*K*sizeof(float),cudaMemcpyDeviceToHost));double maxerr=0;for(int i=0;i<K;i++)for(int j=0;j<K;j++){double expected=0;if(i!=j)for(int p=offs[i];p<offs[i+1];p++)for(int q=offs[j];q<offs[j+1];q++)expected+=ws[p]*ws[q]*(2.+(S.count(ls[p])!=S.count(ls[q])));maxerr=fmax(maxerr,fabs(D[i*K+j]-expected));}double change=score_skeleton(K,D,true)-score_skeleton(K,D,false);printf("actual recovery CUDA kernel N=%d K=%d cap=128 condensed_entries=%d max_matrix_error=%.17g GPU_change=%.17g full_true_change=%.17g\n",N,K,offs[1],maxerr,change,big?.234375:.029296875);if(maxerr>1e-6||fabs(change-(big?-.25:.029296875))>1e-6)return 1;cudaFree(doff);cudaFree(dl);cudaFree(dw);cudaFree(dD);oracle.destroy();}return 0;}
